//! Federated continual evidence-surveillance workflow fabric for `AFA-oracle-P01-F16`.
//!
//! Schedules a bounded, checkpointed evidence review over aggregate peer attestations. The
//! fabric never fetches literature, reads raw data, executes tools, or makes clinical decisions.

use bioprism_foundation::{AuthorityRequirement, AutonomyTier, CapabilityManifest, Determinism, Effect, EvidenceReference, EvidenceState, ResearchSurface, TypedPort, TypedResearchArtifact, PRECLINICAL_BOUNDARY, RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize, Serialize};
use serde_json::json;
use std::collections::BTreeSet;
use thiserror::Error;

pub const FEATURE_ID: &str = "AFA-oracle-P01-F16";
pub const CONTRACT_VERSION: &str = "oracle-federated-continual-evidence-surveillance-workflow-fabric/1.0";
pub const INPUT_SCHEMA: &str = "EvidenceFeed4@1";
pub const OUTPUT_SCHEMA: &str = "QualifiedEvidenceSet4@1";
pub const CONTENT_TYPE: &str = "application/vnd.aurora.oracle-qualified-evidence-set-4+json";
pub const CANONICAL_STAGES: [&str; 4] = ["stage:checkpoint", "stage:admit-federation", "stage:surveil-evidence", "stage:seal-envelope"];

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct EvidenceContribution4 { pub candidate_id:String, pub peer_id:String, pub source_id:String, pub artifact_kind:String, pub semantic_profile:String, pub digest:ContentHash, pub replay_identity:ContentHash, pub evidence_state:EvidenceState, pub relevance_milli:u16, pub signed:bool, pub permitted_artifact:bool, pub aggregate_only:bool, pub raw_data_local:bool, pub negative_result:bool, pub omission_order:Vec<String> }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct EvidenceSurveillanceWorkflowRequest { pub request_id:String, pub workflow_id:String, pub federation_id:String, pub purpose:String, pub endpoint:String, pub semantic_profile:String, pub allowed_artifacts:Vec<String>, pub requested_stage_order:Vec<String>, pub checkpoint_id:String, pub budget_units:u32, pub max_budget_units:u32, pub min_peer_quorum:u32, pub replay_identity:ContentHash, pub policy_allow:bool, pub protected_closure:bool, pub federation_approved:bool, pub signed_approval:bool, pub raw_data_local:bool, pub aggregate_only:bool, pub boundary:String, pub contributions:Vec<EvidenceContribution4> }
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct QualifiedEvidenceSet4 { pub schema_version:String, pub contract_version:String, pub feature_id:String, pub request_id:String, pub workflow_id:String, pub federation_id:String, pub disposition:String, pub stage_order:Vec<String>, pub candidate_order:Vec<String>, pub qualified_order:Vec<String>, pub unresolved_order:Vec<String>, pub blocked_order:Vec<String>, pub peer_order:Vec<String>, pub qualified_peer_order:Vec<String>, pub missing_peer_order:Vec<String>, pub omission_order:Vec<String>, pub uncertainty_order:Vec<String>, pub negative_evidence_order:Vec<String>, pub checkpoint_digest:ContentHash, pub workflow_digest:ContentHash, pub artifact:TypedResearchArtifact, pub effect_receipts:Vec<String>, pub raw_data_local:bool, pub aggregate_only:bool, pub boundary:String }
#[derive(Debug, Error, Clone, PartialEq, Eq)]
pub enum EvidenceWorkflowError { #[error("invalid evidence workflow request: {0}")] Invalid(String), #[error("evidence workflow artifact failed: {0}")] Artifact(String) }
fn ordered(v:&[String])->bool { v.windows(2).all(|w|w[0]<w[1]) }
fn valid_digest(v:&ContentHash)->bool { v.as_str().len()==64 }

pub fn evidence_surveillance_workflow_manifest()->CapabilityManifest { CapabilityManifest { schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(), capability_id:FEATURE_ID.into(), version:CONTRACT_VERSION.into(), owner_crate:"oracle".into(), consumers:BTreeSet::from(["imaging core scientist".into(),"evidence workflow operator".into(),"federation steward".into()]), behavior:"schedule checkpointed federated evidence surveillance over signed aggregate attestations without fetching sources".into(), value:"turns continual evidence feeds into replayable workflow receipts while preserving negative and missing evidence".into(), inputs:vec![TypedPort{name:"evidence_feed".into(),schema:INPUT_SCHEMA.into(),required:true}], outputs:vec![TypedPort{name:"qualified_evidence_set".into(),schema:OUTPUT_SCHEMA.into(),required:true}], effects:BTreeSet::from([Effect::ReadLocalData,Effect::WriteLocalArtifact,Effect::FederationExport]), permissions:BTreeSet::from(["execute:approved-workflows".into(),"exchange:permitted-summaries".into()]), determinism:Determinism::ByteStable, evidence:vec![EvidenceReference{source_id:"mcp-2025-06-18".into(),state:EvidenceState::Supported,locator:Some("https://modelcontextprotocol.io/specification/2025-06-18/basic/index".into())}], authority_requirements:vec![AuthorityRequirement{role:"evidence-workflow-operator".into(),reason:"approve bounded aggregate evidence surveillance".into()}], autonomy_tier:AutonomyTier::A2, surfaces:BTreeSet::from([ResearchSurface::Api,ResearchSurface::Sdk,ResearchSurface::McpTool,ResearchSurface::Protocol,ResearchSurface::Policy,ResearchSurface::Operator]), boundary:PRECLINICAL_BOUNDARY.into() } }
impl QualifiedEvidenceSet4 { pub fn validate(&self)->Result<(),EvidenceWorkflowError>{ if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.contract_version!=CONTRACT_VERSION||self.feature_id!=FEATURE_ID||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.boundary!=PRECLINICAL_BOUNDARY||!self.raw_data_local||!self.aggregate_only||self.request_id.trim().is_empty()||self.workflow_id.trim().is_empty()||self.federation_id.trim().is_empty()||self.stage_order!=CANONICAL_STAGES||self.candidate_order.is_empty()||self.peer_order.is_empty()||self.effect_receipts.is_empty(){return Err(EvidenceWorkflowError::Invalid("workflow identity, stages, candidates, peers, locality, or effects are incomplete".into()))} for v in [&self.candidate_order,&self.qualified_order,&self.unresolved_order,&self.blocked_order,&self.peer_order,&self.qualified_peer_order,&self.missing_peer_order,&self.omission_order,&self.uncertainty_order,&self.negative_evidence_order,&self.effect_receipts]{if !ordered(v){return Err(EvidenceWorkflowError::Invalid("workflow ordering is not canonical".into()))}} let ids=BTreeSet::from_iter(self.candidate_order.iter().cloned());let parts=self.qualified_order.iter().chain(&self.unresolved_order).chain(&self.blocked_order).cloned().collect::<BTreeSet<_>>();if ids!=parts||ids.len()!=self.candidate_order.len(){return Err(EvidenceWorkflowError::Invalid("candidate states do not partition".into()))}let peers=BTreeSet::from_iter(self.peer_order.iter().cloned());let p=self.qualified_peer_order.iter().chain(&self.missing_peer_order).cloned().collect::<BTreeSet<_>>();if peers!=p||peers.len()!=self.peer_order.len(){return Err(EvidenceWorkflowError::Invalid("peer states do not partition".into()))}if self.artifact.content_type!=CONTENT_TYPE||self.artifact.content_hash!=self.workflow_digest||!valid_digest(&self.checkpoint_digest)||!valid_digest(&self.workflow_digest){return Err(EvidenceWorkflowError::Artifact("workflow artifact or digest is inconsistent".into()))}if self.effect_receipts.iter().any(|e|!e.starts_with("execute:evidence-surveillance:")&&e!="block:unsafe-release"){return Err(EvidenceWorkflowError::Invalid("workflow effect is outside governed gate".into()))}Ok(())} pub fn digest(&self)->Result<ContentHash,EvidenceWorkflowError>{self.validate()?;ContentHash::of_value(&serde_json::to_value(self).map_err(|e|EvidenceWorkflowError::Artifact(e.to_string()))?).map_err(|e|EvidenceWorkflowError::Artifact(e.to_string()))} }

pub fn schedule_evidence_surveillance(request:&EvidenceSurveillanceWorkflowRequest)->Result<QualifiedEvidenceSet4,EvidenceWorkflowError>{ if request.request_id.trim().is_empty()||request.workflow_id.trim().is_empty()||request.federation_id.trim().is_empty()||request.purpose.trim().is_empty()||request.endpoint.trim().is_empty()||request.semantic_profile.trim().is_empty()||request.requested_stage_order!=CANONICAL_STAGES.iter().map(|s|s.to_string()).collect::<Vec<_>>()||request.checkpoint_id.trim().is_empty()||request.budget_units==0||request.max_budget_units==0||request.budget_units>request.max_budget_units||request.min_peer_quorum==0||!request.raw_data_local||!request.aggregate_only||request.boundary!=PRECLINICAL_BOUNDARY||!valid_digest(&request.replay_identity)||request.contributions.is_empty(){return Err(EvidenceWorkflowError::Invalid("workflow identity, stages, budget, locality, replay, or boundary is invalid".into()))}let mut rows=request.contributions.clone();rows.sort_by(|a,b|a.peer_id.cmp(&b.peer_id).then(a.candidate_id.cmp(&b.candidate_id)));let candidate_order=rows.iter().map(|r|r.candidate_id.clone()).collect::<BTreeSet<_>>().into_iter().collect::<Vec<_>>();let peer_order=rows.iter().map(|r|r.peer_id.clone()).collect::<BTreeSet<_>>().into_iter().collect::<Vec<_>>();let mut qualified=BTreeSet::new();let mut unresolved=BTreeSet::new();let mut blocked=BTreeSet::new();let mut qualified_peers=BTreeSet::new();let mut omissions=BTreeSet::new();let mut uncertainty=BTreeSet::new();let mut negative=BTreeSet::new();for r in &rows{for o in &r.omission_order{omissions.insert(format!("{}:{}",r.candidate_id,o));}if r.negative_result{negative.insert(format!("{}:negative-result",r.candidate_id));}let ok=r.semantic_profile==request.semantic_profile&&r.replay_identity==request.replay_identity&&r.signed&&r.permitted_artifact&&r.aggregate_only&&r.raw_data_local&&r.relevance_milli>=500&&request.allowed_artifacts.contains(&r.artifact_kind);if r.evidence_state==EvidenceState::Contradicted{blocked.insert(r.candidate_id.clone());negative.insert(format!("{}:contradicted",r.candidate_id));}else if !ok||!matches!(r.evidence_state,EvidenceState::Proven|EvidenceState::Supported){unresolved.insert(r.candidate_id.clone());uncertainty.insert(format!("{}:unresolved",r.candidate_id));}else{qualified.insert(r.candidate_id.clone());qualified_peers.insert(r.peer_id.clone());}}let missing_peer_order=peer_order.iter().filter(|p|!qualified_peers.contains(*p)).cloned().collect::<Vec<_>>();if qualified_peers.len()<(request.min_peer_quorum as usize){omissions.insert(format!("peer-quorum:{}/{}",qualified_peers.len(),request.min_peer_quorum));}let global_block=!request.policy_allow||!request.protected_closure||!request.federation_approved||!request.signed_approval;if !request.policy_allow{omissions.insert("workflow:policy-denied".into());}if !request.protected_closure{omissions.insert("workflow:protected-closure-incomplete".into());}if !request.federation_approved{omissions.insert("workflow:federation-approval-missing".into());}if !request.signed_approval{omissions.insert("workflow:signed-approval-missing".into());}let disposition=if global_block||!blocked.is_empty(){"blocked"}else if qualified_peers.len()<(request.min_peer_quorum as usize)||!unresolved.is_empty()||!negative.is_empty(){"unresolved"}else{"qualified"};if disposition!="qualified"{omissions.insert("workflow:closure-incomplete".into());}if global_block{blocked.extend(candidate_order.iter().cloned());qualified.clear();unresolved.clear();}let completed_order=qualified.iter().cloned().collect::<Vec<_>>();let checkpoint_digest=ContentHash::of_value(&json!({"workflow_id":request.workflow_id,"checkpoint_id":request.checkpoint_id,"stage_order":request.requested_stage_order,"replay_identity":request.replay_identity})).map_err(|e|EvidenceWorkflowError::Artifact(e.to_string()))?;let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":CONTRACT_VERSION,"feature_id":FEATURE_ID,"request_id":request.request_id,"workflow_id":request.workflow_id,"federation_id":request.federation_id,"disposition":disposition,"stage_order":request.requested_stage_order,"candidate_order":candidate_order,"qualified_order":completed_order,"unresolved_order":unresolved,"blocked_order":blocked,"peer_order":peer_order,"qualified_peer_order":qualified_peers,"missing_peer_order":missing_peer_order,"omission_order":omissions,"uncertainty_order":uncertainty,"negative_evidence_order":negative,"checkpoint_digest":checkpoint_digest,"replay_identity":request.replay_identity,"boundary":PRECLINICAL_BOUNDARY});let workflow_digest=ContentHash::of_value(&payload).map_err(|e|EvidenceWorkflowError::Artifact(e.to_string()))?;let artifact=TypedResearchArtifact::from_payload(format!("oracle-evidence-workflow:{}",request.workflow_id),CONTENT_TYPE,&payload,Vec::new(),Vec::new()).map_err(|e|EvidenceWorkflowError::Artifact(e.to_string()))?;let effect_receipts=if disposition=="qualified"{vec![format!("execute:evidence-surveillance:{}",request.workflow_id)]}else{vec!["block:unsafe-release".into()]};let out=QualifiedEvidenceSet4{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:CONTRACT_VERSION.into(),feature_id:FEATURE_ID.into(),request_id:request.request_id.clone(),workflow_id:request.workflow_id.clone(),federation_id:request.federation_id.clone(),disposition:disposition.into(),stage_order:request.requested_stage_order.clone(),candidate_order:payload["candidate_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),qualified_order:payload["qualified_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),unresolved_order:payload["unresolved_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),blocked_order:payload["blocked_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),peer_order:payload["peer_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),qualified_peer_order:payload["qualified_peer_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),missing_peer_order:payload["missing_peer_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),omission_order:payload["omission_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),uncertainty_order:payload["uncertainty_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),negative_evidence_order:payload["negative_evidence_order"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),checkpoint_digest,workflow_digest:workflow_digest.clone(),artifact,effect_receipts,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}

#[cfg(test)]mod tests{use super::*;fn h(v:&str)->ContentHash{ContentHash::of_bytes(v.as_bytes())}fn req()->EvidenceSurveillanceWorkflowRequest{EvidenceSurveillanceWorkflowRequest{request_id:"r".into(),workflow_id:"w".into(),federation_id:"f".into(),purpose:"surveil".into(),endpoint:"local://federation".into(),semantic_profile:"profile:v1".into(),allowed_artifacts:vec!["summary".into()],requested_stage_order:CANONICAL_STAGES.iter().map(|s|s.to_string()).collect(),checkpoint_id:"c".into(),budget_units:4,max_budget_units:4,min_peer_quorum:1,replay_identity:h("replay"),policy_allow:true,protected_closure:true,federation_approved:true,signed_approval:true,raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into(),contributions:vec![EvidenceContribution4{candidate_id:"e1".into(),peer_id:"p1".into(),source_id:"s1".into(),artifact_kind:"summary".into(),semantic_profile:"profile:v1".into(),digest:h("d"),replay_identity:h("replay"),evidence_state:EvidenceState::Supported,relevance_milli:900,signed:true,permitted_artifact:true,aggregate_only:true,raw_data_local:true,negative_result:false,omission_order:vec![]}]}}#[test]fn manifest_is_a2(){assert_eq!(evidence_surveillance_workflow_manifest().autonomy_tier,AutonomyTier::A2)}#[test]fn qualified_schedule(){assert_eq!(schedule_evidence_surveillance(&req()).unwrap().disposition,"qualified")}#[test]fn policy_blocks(){let mut r=req();r.policy_allow=false;assert_eq!(schedule_evidence_surveillance(&r).unwrap().disposition,"blocked")}#[test]fn negative_is_unresolved(){let mut r=req();r.contributions[0].negative_result=true;assert_eq!(schedule_evidence_surveillance(&r).unwrap().disposition,"unresolved")}#[test]fn deterministic(){assert_eq!(schedule_evidence_surveillance(&req()).unwrap(),schedule_evidence_surveillance(&req()).unwrap())}}
